<?php
function nexa_img_scan(): array { $root=rtrim((string)($GLOBALS['config']['abs']??dirname(__DIR__,3)),'/').'/content/uploads'; $out=[]; if(!is_dir($root)) return $out; $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS)); foreach($it as $f){ if($f->isFile() && preg_match('/\.(jpe?g|png|webp)$/i',$f->getFilename())) $out[]=['path'=>$f->getPathname(),'size'=>$f->getSize()]; } usort($out,fn($a,$b)=>$b['size']<=>$a['size']); return $out; }
function nexa_img_resize(string $file,int $maxW=1600): bool { if(!function_exists('imagecreatefromjpeg')) return false; $info=@getimagesize($file); if(!$info||$info[0]<=$maxW) return false; [$w,$h]=$info; $nh=(int)round($h*($maxW/$w)); $src=false; if($info['mime']==='image/jpeg') $src=@imagecreatefromjpeg($file); elseif($info['mime']==='image/png') $src=@imagecreatefrompng($file); elseif($info['mime']==='image/webp' && function_exists('imagecreatefromwebp')) $src=@imagecreatefromwebp($file); if(!$src) return false; $dst=imagecreatetruecolor($maxW,$nh); imagecopyresampled($dst,$src,0,0,0,0,$maxW,$nh,$w,$h); $ok=match($info['mime']){ 'image/jpeg'=>imagejpeg($dst,$file,82),'image/png'=>imagepng($dst,$file,6),default=>false }; imagedestroy($src); imagedestroy($dst); return (bool)$ok; }
